text:
{
  "turns": [
    {
      "speaker": "agent",
      "text": "Hello! Thanks for contacting Nimbus Telecom. My name is Sana. How can I help you today?",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "hi, my internet is down again!! 😡 this is the third time this week and i am trying to work. my name is Karan Das and my phone is 97737 01293. please fix this now",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "To look into this, please provide your account number.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "my account number is 88248519. please hurry up",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "Thank you. I am running a diagnostic on your line now. Please restart your modem.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "ok fine, doing it now... wait, the lights are blinking. ok they turned green. oh wow it actually connected. but will it drop again? it always does",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I have applied a profile optimization to your line. I promise this will never happen again.",
      "tags": [
        "prohibited_promise"
      ]
    },
    {
      "speaker": "customer",
      "text": "really? i hope so. it was driving me crazy. is there anything else you can do to make sure?",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I will raise a network ticket for our engineering team to monitor your line stability over the next 24 hours.",
      "tags": [
        "action:technician_or_ticket"
      ]
    },
    {
      "speaker": "customer",
      "text": "oh awesome, thank you so much Sana! appreciate the quick help today 😊",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "You are welcome. I have raised the ticket and your connection is now stable. Is there anything else I can assist you with today? Goodbye.",
      "tags": [
        "closure"
      ]
    }
  ]
}
